B.Tw=new A.ef("3D \ub098\ub178\ucf54\ud305(Nano Coating)\uc774\ub780 \uc815\ud655\ud788 \ubb34\uc5c7\uc778\uac00\uc694?","3D \ub098\ub178\ucf54\ud305\uc740 \uba54\ud0c8\ub9c8\uc2a4\ud06c\uc758 \ubbf8\uc138 \uac1c\uad6c\ubd80 \ub0b4\ubcbd\uacfc \ud45c\uba74\uc5d0 \ubd84\uc790 \ub2e8\uc704\uc758 \ucd08\ubc1c\uc218\xb7\ucd08\ubc1c\uc720 \ub098\ub178 \ubc15\ub9c9\uc744 \ud615\uc131\ud558\ub294 \ud45c\uba74 \uac1c\uc9c8 \uae30\uc220\uc785\ub2c8\ub2e4.\n\n\uc194\ub354 \ud398\uc774\uc2a4\ud2b8\uc640 \uae08\uc18d \ud45c\uba74 \uc0ac\uc774\uc758 \ub9c8\ucc30 \uc800\ud56d\uc744 \ud68d\uae30\uc801\uc73c\ub85c \ub0ae\ucd94\uc5b4, \ub9c8\uc2a4\ud06c \ubd84\ub9ac \uc2dc \uc194\ub354\uac00 \ubcbd\uba74\uc5d0 \ub0a8\uc9c0 \uc54a\uace0 \uae30\ud310\uc5d0 \uae68\ub057\ud558\uac8c \uc804\uc0ac\ub418\ub3c4\ub85d \ub3d5\ub294 \uc720\ud53c\ud14c\ud06c\uc758 \uc815\ubc00 \ucf54\ud305 \uae30\uc220\uc785\ub2c8\ub2e4.")
B.Tt=new A.ef("\uc77c\ubc18 \ub098\ub178\ucf54\ud305\uacfc \uc720\ud53c\ud14c\ud06c\uc758 3D \ub098\ub178\ucf54\ud305\uc740 \uc5b4\ub5a4 \ucc28\uc774\uac00 \uc788\ub098\uc694?","\uc77c\ubc18 \uc2b5\uc2dd \ucf54\ud305\uc740 \uc561\uc0c1 \ucf54\ud305\uc81c\ub97c \ub2e8\uc21c\ud788 \ub3c4\ud3ec\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c, \uac1c\uad6c\ubd80 \ub0b4\ubcbd\uae4c\uc9c0 \uade0\uc77c\ud558\uac8c \uce68\ud22c\ud558\uc9c0 \ubabb\ud558\uace0 \ub9c8\ucc30 \ubc0f \uc138\ucc99 \uc2dc \uc27d\uac8c \ubc15\ub9ac\ub418\ub294 \ub2e8\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4.\n\n\uc720\ud53c\ud14c\ud06c 3D \ub098\ub178\ucf54\ud305\uc740 \ub300\uae30\uc555 \ud50c\ub77c\uc988\ub9c8 \ud45c\uba74 \ud65c\uc131\ud654 \ud6c4 \ubd88\uc18c\uacc4 \ub098\ub178 \ubb3c\uc9c8\uc744 \ud654\ud559\uc801 \uacf5\uc720 \uacb0\ud569\uc73c\ub85c \ud761\ucc29\uc2dc\ud0a4\uace0 \uc5f4\uacbd\ud654\ud569\ub2c8\ub2e4. \uc218\uc9c1 \ub0b4\ubcbd\uae4c\uc9c0 \uade0\uc77c\ud55c \ub2e8\uc77c \ubd84\uc790\ub9c9\uc744 \ud615\uc131\ud558\uc5ec \ubc18\ubcf5\uc801\uc778 \uc778\uc1c4\uc640 \uc138\ucc99\uc5d0\ub3c4 \uc624\ub79c \uc2dc\uac04 \uc548\uc815\uc801\uc778 \ub0b4\uad6c\uc131\uc744 \uc720\uc9c0\ud569\ub2c8\ub2e4.")
